function buzz(ms=20){if(save.settings.haptics&&navigator.vibrate)navigator.vibrate(ms)}
function sprite(){return '<div class="head"><i class="eye l"></i><i class="eye r"></i></div><div class="body"></div><div class="arm l"></div><div class="arm r"></div><div class="leg l"></div><div class="leg r"></div>'}
function classFor(name){return CHARS[name]?.cls||LEVELS.find(l=>l.name===name)?.cls||(name==='Training Dummy'?'dummy':name.toLowerCase().replace(/[^a-z0-9]+/g,''))}
function skinById(id){return SKINS.find(s=>s.id===id)||null}
function skinClassFor(name,skinId=null){if(!CHARS[name])return'';const id=skinId||save.equippedSkins[name]||DEFAULT_SKIN_BY_HERO[name],s=skinById(id);return s&&s.hero===name&&save.skinsOwned[id]?s.cls:''}
function fighterStatsFor(name){const c=CHARS[name];if(name==='Iron Man'&&save.equippedSkins['Iron Man']==='iron-hulkbuster')return{...c,hp:175,power:98,speed:48,punch:16,kick:22,special:58,specialName:'Veronica Crashdown',role:'HEAVY ASSAULT',powerClass:'HULKBUSTER ARMOR'};return c}
function equippedDisplaySkin(name){const id=save.equippedSkins[name],s=skinById(id),defaultId=DEFAULT_SKIN_BY_HERO[name];return s&&s.hero===name&&save.skinsOwned[id]&&defaultId&&id!==defaultId?s:null}
function fighterDisplayName(name){return equippedDisplaySkin(name)?.name||name}
window.FightArenaNameControls={display:name=>fighterDisplayName(name),skin:name=>equippedDisplaySkin(name)?.name||null,stats:name=>({...fighterStatsFor(name)})};
function previewMarkup(name,skinId=null){const skin=skinId&&skinById(skinId)?.hero===name?skinById(skinId)?.cls:skinClassFor(name);return `<div class="fighter ${classFor(name)} ${skin||''} idle" style="position:relative;left:auto;bottom:auto">${sprite()}</div>`}
function setSprite(el,name,side,skinId=null){if(!el)return;el.className=`fighter ${side} ${classFor(name)} ${skinClassFor(name,skinId)} idle`;el.innerHTML=sprite()}
function hud(){$('coins').textContent=save.coins;$('gems').textContent=save.gems;$('lv').textContent=save.lv;$('selectedName').textContent=fighterDisplayName(save.selected).toUpperCase();$('homePreview').innerHTML=previewMarkup(save.selected)}
function refreshDashboard(){const vis=visibleChars(),owned=vis.filter(([n])=>save.owned[n]).length,n=clamp(save.unlocked,1,LEVELS.length),target=LEVELS[n-1];$('dashHero').textContent=fighterDisplayName(save.selected).toUpperCase();$('dashRoster').textContent=`${owned}/${vis.length}`;$('dashTarget').textContent=target.name.toUpperCase();$('dashLevel').textContent=`Campaign Level ${target.n}`;$('dashCoins').textContent=`${save.coins} 🪙`}
function renderChars(){
 const box=$('charCards');box.innerHTML='';box.classList.add('rank-groups');
 const entries=visibleChars();
 RANK_ORDER.forEach(rank=>{
   const fighters=entries.filter(([,c])=>c.arenaRank===rank);if(!fighters.length)return;
   const group=document.createElement('section');group.className=`rank-group rank-${rank.replace('+','plus').replace('∞','owner').toLowerCase()}`;
   const prices=fighters.filter(([,c])=>c.price>0).map(([,c])=>c.price),minPrice=prices.length?Math.min(...prices):0,maxPrice=prices.length?Math.max(...prices):0,priceText=prices.length?(minPrice===maxPrice?`${minPrice.toLocaleString()} 🪙`:`${minPrice.toLocaleString()}–${maxPrice.toLocaleString()} 🪙`):'SPECIAL ACCESS';
   group.innerHTML=`<div class="rank-group-head"><div><span>${RANK_INFO[rank].label}</span><small>${RANK_INFO[rank].desc}</small></div><b>${priceText}</b></div><div class="rank-fighters-grid"></div>`;
   const grid=group.querySelector('.rank-fighters-grid');
   fighters.sort((a,b)=>b[1].price-a[1].price).forEach(([name,c])=>{const b=document.createElement('button');b.className='card '+(chosen===name?'active ':'')+(!save.owned[name]?'locked ':'')+(name===OWNER?'owner-card ':'');b.innerHTML=`<div class="rank-card-top"><span class="rank-chip">${c.arenaRank} RANK</span><span class="power-chip">${c.powerClass}</span></div><div class="portrait">${previewMarkup(name)}</div><h3>${name.toUpperCase()}</h3><div class="fighter-role">${c.role}</div><small>${save.owned[name]?(save.selected===name?'✓ SELECTED':'OWNED'):`🪙 ${c.price.toLocaleString()}`}</small>`;b.onclick=()=>{chosen=name;renderChars();renderCharInfo()};grid.appendChild(b)});
   box.appendChild(group);
 });
 const vis=entries,owned=vis.filter(([n])=>save.owned[n]).length;$('gallerySummary').innerHTML=`<div><b>RANKED FIGHTER ROSTER</b><span> ${owned} owned • ${vis.length} total • Higher rank = higher price</span></div><div class="role-chip">${fighterDisplayName(save.selected).toUpperCase()} SELECTED</div>`
}
function renderCharInfo(){
 const c=fighterStatsFor(chosen),kit=activeFighterKit(chosen),heroSkins=SKINS.filter(s=>s.hero===chosen),ownedSkins=heroSkins.filter(s=>save.skinsOwned[s.id]).length;
 $('charTitle').textContent=fighterDisplayName(chosen).toUpperCase();$('charDesc').textContent=c.desc;
 $('charStats').innerHTML=`<div><small>ARENA RANK</small>${c.arenaRank}</div><div><small>POWER CLASS</small>${c.powerClass}</div><div><small>ROLE</small>${c.role}</div><div><small>PRICE</small>${c.campaignOnly?'CAMPAIGN UNLOCK':c.price?c.price.toLocaleString()+' 🪙':'STARTER'}</div><div><small>HEALTH</small>${c.hp}</div><div><small>POWER</small>${c.power}</div><div><small>SPEED</small>${c.speed}</div><div><small>SUITS</small>${ownedSkins}/${heroSkins.length}</div>`;
 let panel=$('fighterKitPanel');if(!panel){panel=document.createElement('div');panel.id='fighterKitPanel';panel.className='fighter-kit-panel';$('charStats').insertAdjacentElement('afterend',panel)}
 panel.innerHTML=`<div class="kit-title"><div><small>COMBAT IDENTITY</small><b>${c.role}</b></div><span>${c.arenaRank} RANK • ${c.powerClass}</span></div><div class="kit-section"><small>ABILITIES</small><div class="kit-chips">${kit.abilities.map(a=>`<span>${a}</span>`).join('')}</div></div><div class="kit-bottom"><div><small>PASSIVE</small><b>${kit.passive}</b></div><div><small>SPECIAL</small><b>${kit.special}</b></div></div>`;
 $('charAction').textContent=!save.owned[chosen]?`BUY • ${c.price.toLocaleString()} 🪙`:save.selected===chosen?'SELECTED':'SELECT';$('charAction').disabled=save.selected===chosen
}function showCollectionTab(tab='fighters'){collectionTab=tab;document.querySelectorAll('[data-collection-tab]').forEach(b=>b.classList.toggle('active',b.dataset.collectionTab===tab));$('fightersPane')?.classList.toggle('hidden',tab!=='fighters');$('skinsPane')?.classList.toggle('hidden',tab!=='skins');if(tab==='fighters'){renderChars();renderCharInfo()}else{renderSkins();renderSkinInfo()}}
function renderSkins(){
 const box=$('skinCards');if(!box)return;box.innerHTML='';box.classList.add('skin-hero-groups');
 const heroes=[];RANK_ORDER.forEach(rank=>visibleChars().filter(([name,c])=>c.arenaRank===rank&&SKINS.some(s=>s.hero===name)).sort((a,b)=>b[1].price-a[1].price).forEach(([name])=>heroes.push(name)));
 heroes.forEach(hero=>{const list=SKINS.filter(s=>s.hero===hero),c=CHARS[hero],ownedCount=list.filter(s=>save.skinsOwned[s.id]).length,group=document.createElement('section');group.className='skin-hero-group';group.innerHTML=`<div class="skin-hero-head"><div><small>${c.arenaRank} RANK • ${c.role}</small><b>${hero.toUpperCase()}</b></div><span>${ownedCount}/${list.length} SUITS OWNED</span></div><div class="skin-hero-grid"></div>`;const grid=group.querySelector('.skin-hero-grid');
 list.forEach(s=>{const heroOwned=!!save.owned[s.hero],owned=!!save.skinsOwned[s.id],equipped=save.equippedSkins[s.hero]===s.id,type=s.variant?'ABILITY VARIANT':s.price===0?'DEFAULT SUIT':'COSMETIC SKIN',b=document.createElement('button');b.className=`card skin-card rarity-${s.rarity.toLowerCase()} ${skinChosen===s.id?'active ':''}${!heroOwned?'hero-locked ':''}${equipped?'equipped-skin ':''}${s.variant?'ability-variant-card ':''}`;b.innerHTML=`<div class="skin-card-head"><span class="skin-type-chip ${s.variant?'variant':''}">${s.variant?'⚡ ':''}${type}</span><span class="skin-rarity-chip">${s.rarity}</span></div><div class="portrait skin-portrait">${previewMarkup(s.hero,s.id)}</div><h3>${s.name.toUpperCase()}</h3><p class="skin-card-desc">${s.variant?'Changes suit + abilities + special':s.price===0?'Included base appearance':'Appearance-only cosmetic'}</p><small>${!heroOwned?'🔒 OWN HERO FIRST':equipped?'✓ EQUIPPED':owned?'OWNED':`💎 ${s.price}`}</small>`;b.onclick=()=>{skinChosen=s.id;renderSkins();renderSkinInfo()};grid.appendChild(b)});
 box.appendChild(group)
 })
}function renderSkinInfo(){
 const s=skinById(skinChosen)||SKINS[0],heroOwned=!!save.owned[s.hero],owned=!!save.skinsOwned[s.id],equipped=save.equippedSkins[s.hero]===s.id,type=s.variant?'ABILITY VARIANT':s.price===0?'DEFAULT SUIT':'COSMETIC SKIN';
 $('skinTitle').textContent=s.name.toUpperCase();$('skinHero').textContent=s.hero.toUpperCase();$('skinRarity').textContent=`${s.rarity} • ${type}`;$('skinDesc').textContent=s.desc;$('skinPreview').innerHTML=previewMarkup(s.hero,s.id);$('skinPrice').textContent=s.price?`${s.price} 💎`:'INCLUDED';
 let info=$('skinTypeInfo');if(!info){info=document.createElement('div');info.id='skinTypeInfo';info.className='skin-type-info';$('skinDesc').insertAdjacentElement('afterend',info)}
 info.innerHTML=s.variant?'<b>⚡ ABILITY VARIANT</b><span>Changes appearance, hero abilities and Special.</span>':s.price===0?'<b>✓ DEFAULT SUIT</b><span>Included with the fighter. Original combat kit.</span>':'<b>◆ COSMETIC SKIN</b><span>Appearance only. Combat stats and abilities stay unchanged.</span>';
 const a=$('skinAction');a.disabled=!heroOwned||equipped;a.textContent=!heroOwned?'OWN HERO FIRST':equipped?'EQUIPPED':owned?'EQUIP':`BUY • ${s.price} 💎`
}function renderTraining(){const box=$('trainingCards');box.innerHTML='';visibleChars().filter(([n])=>save.owned[n]).forEach(([name,c])=>{const b=document.createElement('button');b.className='card training-card '+(trainingChosen===name?'active ':'')+(name===OWNER?'owner-card ':'');b.innerHTML=`<div class="eyebrow">${c.rank}</div><div class="portrait">${previewMarkup(name)}</div><h3>${fighterDisplayName(name).toUpperCase()}</h3><small>READY TO TRAIN</small>`;b.onclick=()=>{trainingChosen=name;renderTraining();updateTrainingInfo()};box.appendChild(b)});updateTrainingInfo()}
function updateTrainingInfo(){const c=fighterStatsFor(trainingChosen),special=trainingChosen==='Iron Man'&&save.equippedSkins['Iron Man']==='iron-hulkbuster'?'Veronica Crashdown':trainingChosen==='Iron Man'&&save.equippedSkins['Iron Man']==='iron-nano'?'Nanotech Arsenal':trainingChosen==='Black Panther'&&save.equippedSkins['Black Panther']==='bp-kinetic'?'Kinetic Overdrive':c.specialName;$('trainingHero').textContent=fighterDisplayName(trainingChosen).toUpperCase();$('trainingDesc').textContent=`${c.arenaRank} Rank • ${c.powerClass} • ${special} • ${c.hp} HP • ${c.power} Power • ${c.speed} Speed`}
function renderLevels(){const box=$('levelCards');box.innerHTML='';LEVELS.forEach(l=>{const open=l.n<=save.unlocked,b=document.createElement('button');b.className='card '+(chosenLevel===l.n?'active ':'')+(!open?'locked ':'')+(l.boss?'boss-card':'');b.innerHTML=`<div class="eyebrow">LEVEL ${l.n} • ${l.diff} ${l.boss?'<span class="boss-badge">BOSS</span>':''}</div><div class="portrait">${previewMarkup(l.name)}</div><h3>${l.name.toUpperCase()}</h3><div class="level-villain">${l.role}</div><span class="level-reward">${open?`🪙 ${l.coins} • ${l.xp} XP${l.gems?` • 💎 ${l.gems}`:''}`:'🔒 LOCKED'}</span>`;b.onclick=()=>{if(!open)return toast(`Beat Level ${l.n-1} first`);chosenLevel=l.n;renderLevels();renderLevelInfo()};box.appendChild(b)})}
function renderLevelInfo(){const l=LEVELS[chosenLevel-1];$('diff').textContent=l.boss?'BOSS ENCOUNTER':l.diff.toUpperCase();$('levelTitle').textContent=`LEVEL ${l.n} — ${l.name.toUpperCase()}`;$('levelDesc').textContent=l.desc;$('levelStats').innerHTML=`<div><small>HP</small>${l.hp}</div><div><small>DAMAGE</small>${Math.round(l.dmg*100)}%</div><div><small>REWARD</small>${l.coins} 🪙</div><div><small>${l.gems?'BOSS LOOT':'XP'}</small>${l.gems?`${l.gems} 💎`:l.xp}</div>`}
function renderSettings(){document.querySelectorAll('[data-setting]').forEach(b=>{const k=b.dataset.setting,on=!!save.settings[k];b.textContent=on?'ON':'OFF';b.classList.toggle('setting-on',on)})}

const DAILY_REWARD_COINS=1250,DAILY_COOLDOWN_MS=24*60*60*1000;
function dailyRemainingMs(){const stamp=Number(save.dailyClaimAt)||0;return stamp?Math.max(0,DAILY_COOLDOWN_MS-(Date.now()-stamp)):0}
function dailyTimeText(ms){const total=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),s=total%60;return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function claimDailyReward(){const left=dailyRemainingMs();if(left>0)return toast('DAILY REWARD READY IN '+dailyTimeText(left));save.dailyClaimAt=Date.now();save.dailyClaimDate=localDay();save.coins+=DAILY_REWARD_COINS;persist();window.dispatchEvent(new Event('fightarena-daily-updated'));toast('+1,250 COINS 🪙 • NEXT IN 24H')}
function bindClick(id,fn){const el=$(id);if(!el){console.warn('[v0.9.1] missing button',id);return}el.onclick=fn}
function toggleSetting(k){save.settings[k]=!save.settings[k];persist();toast(`${k==='damageNumbers'?'DAMAGE NUMBERS':k==='screenShake'?'SCREEN SHAKE':'HAPTICS'} ${save.settings[k]?'ON':'OFF'}`)}
function floatDamage(n,target='enemy',heal=false){if(!save.settings.damageNumbers)return;const d=document.createElement('div');d.className='damage-number '+(target==='player'?'player-damage ':'')+(heal?'heal-number':'');d.textContent=heal?`+${Math.round(n)}`:`-${Math.round(n)}`;d.style.left=(target==='enemy'?F?.ex:F?.px)+'%';d.style.top=target==='enemy'?'39%':'43%';$('arena')?.appendChild(d);later(()=>d.remove(),700)}
function shake(big=false){if(!save.settings.screenShake)return;const a=$('arena');a.classList.remove('shake','bigshake');void a.offsetWidth;a.classList.add(big?'bigshake':'shake');later(()=>a.classList.remove('shake','bigshake'),250)}
function impact(x,y=48){const d=document.createElement('div');d.className='impact';d.style.left=x+'%';d.style.top=y+'%';$('arena').appendChild(d);later(()=>d.remove(),220)}
function blockFx(x){const d=document.createElement('div');d.className='blockfx';d.style.left=x+'%';d.style.top='40%';$('arena').appendChild(d);later(()=>d.remove(),200)}
function koFx(){const d=document.createElement('div');d.className='ko-banner';d.textContent='K.O.';$('arena')?.appendChild(d);later(()=>d.remove(),700);buzz(70)}

$('charAction').onclick=()=>{const c=CHARS[chosen];if(c.hidden&&!save.ownerGodUnlocked)return toast('OWNER ACCESS REQUIRED');if(!save.owned[chosen]){if(save.coins<c.price)return toast('Not enough coins');save.coins-=c.price;save.owned[chosen]=true}save.selected=chosen;persist();renderChars();renderCharInfo();renderTraining();toast(`${chosen.toUpperCase()} SELECTED`)};
$('skinAction').onclick=()=>{const s=skinById(skinChosen);if(!s)return;if(!save.owned[s.hero])return toast('OWN THE HERO FIRST');if(!save.skinsOwned[s.id]){if(save.gems<s.price)return toast('NOT ENOUGH DIAMONDS');save.gems-=s.price;save.skinsOwned[s.id]=true;toast(`${s.name.toUpperCase()} UNLOCKED 💎`)}save.equippedSkins[s.hero]=s.id;persist();renderSkins();renderSkinInfo();renderChars();renderTraining();if(save.selected===s.hero)hud()};
document.querySelectorAll('[data-collection-tab]').forEach(b=>b.onclick=()=>showCollectionTab(b.dataset.collectionTab));
bindClick('play',()=>{chosenLevel=clamp(save.unlocked,1,LEVELS.length);renderLevels();renderLevelInfo();screen('levels')});
bindClick('gallery',()=>{chosen=save.selected;renderChars();renderCharInfo();showCollectionTab('fighters');screen('chars')});
