function draw(){if(!F)return;$('pF').style.left=F.px+'%';$('eF').style.left=F.ex+'%';$('pF').style.bottom=`calc(14% + ${F.jump}px)`;$('php').style.width=clamp(F.ph/F.pm*100,0,100)+'%';$('ehp').style.width=clamp(F.eh/F.em*100,0,100)+'%';$('sp').style.width=clamp(F.sp,0,100)+'%';$('spText').textContent=Math.floor(clamp(F.sp,0,100))+'%';$('special').disabled=F.sp<100;$('timer').textContent=F.training?'∞':F.time;if(F.training){const elapsed=Math.max(1,(performance.now()-F.trainingStarted)/1000),combo=(performance.now()-F.comboAt<900)?F.comboDamage:0;$('trainingDamage').textContent=Math.round(F.totalDamage);$('trainingHits').textContent=F.hits;$('trainingKos').textContent=F.trainingKos;$('trainingLast').textContent=Math.round(F.lastHit||0);$('trainingCombo').textContent=Math.round(combo||0);$('trainingDps').textContent=(F.totalDamage/elapsed).toFixed(1);const hl=$('trainingHeroStatLabel'),hv=$('trainingHeroStat');if(hl&&hv){if(F.hero==='Black Panther'){hl.textContent='KINETIC ENERGY';hv.textContent=Math.round(F.kinetic||0)+'%'}else if(F.hero==='Wolverine'){hl.textContent='HEALING RECOVERED';hv.textContent=Math.round(F.healRecovered||0)}else{hl.textContent='HERO SYSTEM';hv.textContent='—'}}}}
