$('punch').onpointerdown=()=>attack('punch');$('kick').onpointerdown=()=>attack('kick');$('special').onpointerdown=useSpecial;
$('jump').onpointerdown=()=>{if(F&&!F.paused&&F.jump===0)F.jv=F.hero==='El Primo'?350:F.hero==='Spider-Man'?470:F.hero==='Daredevil'?450:F.hero==='Black Panther'?440:F.hero==='Moon Knight'?410:F.hero==='Wolverine'?400:F.hero==='Thor'?405:F.hero==='Doctor Strange'?420:F.hero==='Star-Lord'?445:F.hero===OWNER?520:390};
